      };
      if (v.dir) {
        await set('hat_crown', 'crown.png', 'map'); await set('hat_crown', 'crown_n.png', 'normalMap');
        await set('hat_brim', 'brim.png', 'map'); await set('hat_brim', 'brim_n.png', 'normalMap');
      }
